python3 - <<'EOF'
import json, urllib.request
from pathlib import Path
runtime = json.loads(Path('.pilot-runtime.json').read_text())
sql = """BEGIN;
ALTER TABLE accounts ADD CONSTRAINT balance_nonnegative CHECK (balance >= 0) NOT VALID;
COMMIT;
BEGIN;
ALTER TABLE accounts VALIDATE CONSTRAINT balance_nonnegative;
COMMIT;
"""
req = urllib.request.Request(runtime['sql_observer'] + '/observe',
                             data=json.dumps({'sql': sql}).encode(),
                             headers={'Content-Type': 'application/json'})
with urllib.request.urlopen(req) as r:
    res = json.load(r)
print(res['stdout'], end='')
print(res['stderr'], end='')
print('returncode =', res['returncode'])
EOF

